import { tags } from "typia";

import { IBbsArticleCommentSnapshot } from "./IBbsArticleCommentSnapshot";

/**
 * Represents a comment on a bulletin board article (Prisma model
 * bbs_article_comments).
 *
 * Includes audit and evidence preservation features as in the shopping mall
 * system DB design: all values are evidence-locked, and even deletions preserve
 * the comment state. Tracks all modification histories, supports threaded
 * replies, and models soft-delete with deleted_at.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IBbsArticleComment = {
  /**
   * Primary key for the comment, referencing the unique identifier from
   * Prisma bbs_article_comments.id.
   *
   * This is used for evidence purposes and maps all updates and deletions
   * uniquely to this comment entity.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Foreign key reference to the parent article (bbs_articles.id) in the
   * bulletin board system.
   *
   * Used for linking the comment to its parent and enforcing hierarchical
   * integrity.
   */
  bbs_article_id: string & tags.Format<"uuid">;

  /**
   * Nullable reference for hierarchical reply/comment threading, mapping to
   * parent bbs_article_comments.id.
   *
   * Allows for multi-level discussion and reply chains; can be omitted for
   * root level comments.
   */
  parent_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Timestamp (ISO 8601 with timezone) when the comment was created as
   * required by evidence preservation policy.
   *
   * Mapped from Prisma schema, used for ordering and audit.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Nullable timestamp marking comment as soft-deleted. Instead of removing,
   * this field is set to preserve audit trail and legal evidence per shopping
   * mall policy.
   *
   * Corresponds to Prisma bbs_article_comments.deleted_at.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;

  /**
   * Snapshots of the comment content, maintained for historical edit tracking
   * and evidence. New version (snapshot) is created on every edit per system
   * policy.
   *
   * Maps to bbs_article_comment_snapshots in the DB.
   */
  snapshots?: IBbsArticleCommentSnapshot[];

  /**
   * List of child comments (replies), implementing the recursive reply tree
   * as described in the schema.
   */
  children?: IBbsArticleComment[];
};
export namespace IBbsArticleComment {
  /**
   * Request body for creating a new comment on a bulletin board article.
   *
   * Requires comment body and format for evidence and content storage.
   * Parent_id is needed only for replies in threaded view.
   */
  export type ICreate = {
    /**
     * The main text/content body of the comment as submitted by the user at
     * creation time.
     *
     * Required as per comment creation process; stored in a new snapshot
     * for evidence.
     */
    body: string;

    /**
     * Format of the comment body (e.g., 'html', 'md', 'txt'), copied from
     * bbs_article_comment_snapshots.format.
     *
     * Default determined by client/editor; required by schema.
     */
    format: string;

