files.packages/api/swagger.json:
{
  "openapi": "3.1.0",
  "paths": {
    "/attachmentFiles": {
      "patch": {
        "summary": "List and search attachment files (Prisma: attachment_files table)",
        "description": "This API operation supports advanced listing and searching of all attachment file entries within the shopping mall system. It processes user-provided filters such as file name, extension, creation date, or associated entity. The endpoint references 'attachment_files', which logs every file uploaded in the system (product images, bulletin board attachments, evidence snapshots, etc). File upload evidence integrity and access control are crucial, so only authorized entities should access listings. Pagination and sorting are mandatory for performance and user experience, and proper error handling is required for invalid or unauthorized requests. Related operations include GET/POST/PUT/DELETE on single attachment files; this should be used for bulk navigation and selection tasks.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IAttachmentFile.IRequest"
              }
            }
          },
          "description": "Filter and pagination options for searching attachment files.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IPageIAttachmentFile"
                }
              }
            },
            "description": "Paginated list of attachment file records."
          }
        }
      },
      "post": {
        "summary": "Register a new attachment file (Prisma: attachment_files table)",
        "description": "This endpoint allows authorized users, admins, or system processes to register new files into the attachment file system. Each posted record must pass validation for correct file name, optional extension, and a valid URL to the stored file. The operation is strictly responsible for database record creation, not the binary file upload itself. Post-creation, the new attachment is available for linking in articles, sales, reviews, etc. Errors should be thrown for already-used URLs, improper naming, or missing required data. Related retrieval/listing operations exist for managing and viewing files.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IAttachmentFile.ICreate"
              }
            }
          },
          "description": "Metadata for creating a new attachment file entry.",
          "required": true
        },
        "responses": {
          "201": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IAttachmentFile"
                }
              }
            },
            "description": "Resulting attachment file entry after creation."
          }
        }
      }
    },
    "/attachmentFiles/{id}": {
      "get": {
        "summary": "Fetch a specific attachment file's metadata (Prisma: attachment_files table)",
        "description": "This operation returns the detailed metadata about an individual attachment file, identified by its UUID. Drawing information from 'attachment_files,' the returned structure includes file name, extension, URL, and timestamps. The endpoint is used both for standard file access and for legal or evidence verification relating to board articles, product information, or transaction records. Only authorized roles should access file metadata, particularly if the file is tied to confidential or private content. Common errors include 'not found' for invalid UUID or 'forbidden' if access is restricted. Other operations cover batch listing and file CRUD actions.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target file's unique identifier (UUID).",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IAttachmentFile"
                }
              }
            },
            "description": "Metadata of the requested attachment file."
          }
        }
      },
      "put": {
        "summary": "Update metadata for an attachment file (Prisma: attachment_files table)",
        "description": "This endpoint is designed for updating metadata records of attachment files, such as after file relocation or renaming, or to correct input mistakes. It applies strictly to the 'attachment_files' table, and the physical file content is not altered—only the metadata. Common use cases include changing the file name after upload, correcting a mistyped extension, or updating the URL if storage paths change. Robust permissions and input validation are essential to prevent abuse and data corruption. On success, the updated record is returned; errors result from invalid input, forbidden access, or missing files.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "UUID of the target attachment file to update.",
            "required": true
          }
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IAttachmentFile.IUpdate"
              }
            }
          },
          "description": "New values for updating attachment file metadata.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IAttachmentFile"
                }
              }
            },
            "description": "Attachment file record after update."
          }
        }
      },
      "delete": {
        "summary": "Delete an attachment file (soft delete in 'attachment_files')",
        "description": "This API operation performs a logical (soft) delete on an attachment file record, ensuring the system's data integrity and auditability. File records are not truly removed but are marked as deleted for legal/evidence purposes. The operation takes the file UUID, verifies permissions, and updates the 'attachment_files' table accordingly. Post-delete, any associated entities (articles, sales content) must not lose links to the file's existence. Only admin or authorized roles may delete files. On success, the record or minimal status is returned; errors are thrown if the file is already deleted, not found, or permission is lacking.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "UUID identifying the attachment file to delete.",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IAttachmentFile"
                }
              }
            },
            "description": "Soft-deleted file record or minimal confirmation response."
          }
        }
      }
    },
    "/bbs/articles": {
      "patch": {
        "summary": "List/search bulletin board articles (Prisma: bbs_articles table)",
        "description": "This endpoint enables complex querying and bulk listing of bulletin board articles, referencing the 'bbs_articles' table. Input filters allow precise retrieval based on time, keyword, status (deleted/active), or creator/user. Typical consumers are admins, moderators, or automated tools reviewing board activity in bulk. Security around private or deleted articles must be enforced, and pagination is mandatory. This operation should only return minimal or summary article data; full article or snapshot details are via per-article GET operations. Error cases include invalid queries or unauthorized access. CRUD for single articles is available separately.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsArticle.IRequest"
              }
            }
          },
          "description": "Search, filtering, and pagination parameters for article listing.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IPageIBbsArticle"
                }
              }
            },
            "description": "Paginated list of matching bulletin board articles."
          }
        }
      },
      "post": {
        "summary": "Create a new board article (Prisma: bbs_articles table)",
        "description": "This endpoint allows authorized users to create a new board article. Input is validated for completeness, safe content, and proper creator reference. Automatically populates timestamps and links to the initial content snapshot (managed in sub-entity). File attachments or further modifications occur via related endpoints and child tables. Used in mall forums, Q&A, or evidence tracking. On error, returns rejection reason (invalid input, blocked, etc.). Related: update, delete, list, or get specific article endpoints.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsArticle.ICreate"
              }
            }
          },
          "description": "Metadata needed to create a board article, including author and content context.",
          "required": true
        },
        "responses": {
          "201": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsArticle"
                }
              }
            },
            "description": "Created article record (without attachments)."
          }
        }
      }
    },
    "/bbs/articles/{id}": {
      "get": {
        "summary": "Fetch a specific board article by ID (Prisma: bbs_articles table)",
        "description": "This operation fetches the complete metadata and summary children for a single bulletin board article by its unique identifier. Details returned may include main article fields, timestamps, status, and associated recursive children if required for context. Used in main article viewing screens or evidence tools. Restricted for deleted, confidential, or limited-access articles; permissions logic required for secure viewing. Related operations enable editing, deletion, or search. Error handling: not found or forbidden per visibility.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "UUID of the bulletin board article to retrieve.",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsArticle"
                }
              }
            },
            "description": "Board article metadata (optionally summary children)."
          }
        }
      },
      "put": {
        "summary": "Update a bulletin board article (Prisma: bbs_articles table, snapshot system)",
        "description": "This endpoint takes Article ID, validates user authority, accepts new article data (usually title/body/context) in the request, and records the update via new snapshot in the related entity. Maintains full edit history for legal evidence; original main record remains untouched except for latest update reference. Used for forum posting, Q&A, admin evidence, or dispute tracking. Errors: forbidden/not owner, not found, validation fail, or attempted edits after deletion. See: create, delete for full lifecycle coverage.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target article UUID to update.",
            "required": true
          }
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsArticle.IUpdate"
              }
            }
          },
          "description": "Updated content/context for the article (creates new snapshot).",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsArticle"
                }
              }
            },
            "description": "Updated article record (post-snapshot creation)."
          }
        }
      },
      "delete": {
        "summary": "Soft delete a board article by ID (Prisma: bbs_articles table, audit policy)",
        "description": "This operation performs a soft delete for the named board article, complying with the legal/evidence policy. The endpoint accepts an article UUID, verifies user authority, and sets the record as deleted. Linked metadata (snapshots, comments) remains accessible for audit trails. Used when users request removal, posts are flagged, or moderation is required. Only proper roles can perform. Errors: forbidden, already deleted, not found. Lifecycle coverage via related create/update/list endpoints.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "UUID of the article to be logically deleted.",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsArticle"
                }
              }
            },
            "description": "Updated record (with deleted_at set) or minimal confirmation."
          }
        }
      }
    },
    "/bbs/articles/{articleId}/comments": {
